@dataclass(frozen=True)
class KOLProfile:
    author: str
    tier: str
    directional_weight: float
    fans: int
    total_predictions: int
    win_rate_5d: float
    bayesian_win_rate_5d: float
    mean_realized_return_5d: float
    payoff_ratio: float
    is_contrarian: bool = False
    is_media: bool = False

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


@dataclass(frozen=True)
class KOLWeightedSentimentResult:
    raw_unweighted_polarity: float
    kol_weighted_polarity: float
    total_posts: int
    elite_alpha_count: int
    contrarian_inverted_count: int
    media_neutralized_count: int
    confidence_score: float
    summary_explanation: str
    post_breakdowns: list[dict[str, Any]] = field(default_factory=list)

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


class KOLCredibilityRegistry:
    """Registry for auditing author track records and weighting social sentiment (Bilingual CN + Global)."""

    def __init__(self, csv_path: str | Path | None = None):
        self.profiles: dict[str, KOLProfile] = {}
        self._load_embedded_defaults()

        # Automatically attempt to load both Chinese (1,445) and Global (1,070) KOL databases
        default_cn_paths = [
            Path("/usr/local/google/home/shwaihe/stock_prediction/data/benchmark/XUEQIU_KOL_ALPHA_PROFILES.csv"),
            Path("../stock_prediction/data/benchmark/XUEQIU_KOL_ALPHA_PROFILES.csv"),
        ]
        default_global_paths = [
            Path("/usr/local/google/home/shwaihe/stock_prediction/data/benchmark/GLOBAL_KOL_ALPHA_PROFILES.csv"),
            Path("../stock_prediction/data/benchmark/GLOBAL_KOL_ALPHA_PROFILES.csv"),
        ]

        if csv_path and Path(csv_path).exists():
            self.load_from_csv(csv_path)
        else:
            for p in default_cn_paths:
                if p.exists():
                    self.load_from_csv(p)
                    break
            for p in default_global_paths:
                if p.exists():
                    self.load_from_csv(p)
                    break

    def _load_embedded_defaults(self) -> None:
        for name, data in EMBEDDED_KOL_PROFILES.items():
            tier = data["tier"]
            weight = TIER_WEIGHT_MAP.get(tier, 0.2)
            self.profiles[name] = KOLProfile(
                author=name,
                tier=tier,
                directional_weight=weight,
                fans=int(data["fans"]),
                total_predictions=int(data["calls"]),
                win_rate_5d=float(data["win_rate_5d"]),
                bayesian_win_rate_5d=float(data["bayesian_wr"]),
                mean_realized_return_5d=float(data["mean_ret_5d"]),
                payoff_ratio=float(data["payoff"]),
                is_contrarian=(tier == "TIER_CONTRARIAN_INDICATOR"),
                is_media=(tier == "TIER_MEDIA_AGGREGATOR"),
            )

    def load_from_csv(self, path: str | Path) -> int:
        """Load full empirical KOL track record CSV."""
        count = 0
        try:
            with open(path, mode="r", encoding="utf-8") as f:
                reader = csv.DictReader(f)
                for row in reader:
                    author = str(row.get("author", "")).strip().lstrip("@")
                    if not author:
                        continue
                    tier = str(row.get("tier", "TIER_NEUTRAL_RETAIL")).strip()
                    weight = TIER_WEIGHT_MAP.get(tier, 0.2)
                    self.profiles[author] = KOLProfile(
                        author=author,
                        tier=tier,
                        directional_weight=weight,
                        fans=int(float(row.get("fans", 0) or 0)),
                        total_predictions=int(float(row.get("total_predictions", 0) or 0)),
                        win_rate_5d=float(row.get("win_rate_5d", 0.5) or 0.5),
                        bayesian_win_rate_5d=float(row.get("bayesian_win_rate_5d", 0.5) or 0.5),
                        mean_realized_return_5d=float(row.get("mean_realized_return_5d", 0.0) or 0.0),
                        payoff_ratio=float(row.get("payoff_ratio", 1.0) or 1.0),
                        is_contrarian=(tier == "TIER_CONTRARIAN_INDICATOR"),
                        is_media=(tier == "TIER_MEDIA_AGGREGATOR" or str(row.get("is_media", "0")) == "1"),
                    )
                    count += 1
            logger.info(f"Loaded {count:,} KOL profiles from {path}")
        except Exception as exc:
            logger.warning(f"Failed to load KOL CSV {path}: {exc}")
        return count

    def get_author_profile(self, author_name: str) -> KOLProfile:
        """Lookup author credibility profile; returns baseline retail profile if unknown."""
        clean_name = str(author_name).strip().lstrip("@")
        if clean_name in self.profiles:
            return self.profiles[clean_name]

        # Heuristic check for unindexed media accounts
        media_keywords = ["新闻", "快讯", "时报", "财联社", "财经", "证券", "同花顺", "格隆汇"]
        if any(k in clean_name for k in media_keywords):
            return KOLProfile(
                author=clean_name,
                tier="TIER_MEDIA_AGGREGATOR",
                directional_weight=0.0,
                fans=10000,
                total_predictions=0,
                win_rate_5d=0.50,
                bayesian_win_rate_5d=0.50,
                mean_realized_return_5d=0.0,
                payoff_ratio=1.0,
                is_contrarian=False,
                is_media=True,
            )

        return KOLProfile(
            author=clean_name,
            tier="TIER_NEUTRAL_RETAIL",
            directional_weight=0.2,
            fans=100,
            total_predictions=0,
            win_rate_5d=0.50,
            bayesian_win_rate_5d=0.50,
            mean_realized_return_5d=0.0,
            payoff_ratio=1.0,
            is_contrarian=False,
            is_media=False,
        )

    def evaluate_weighted_sentiment(
        self,
        posts: list[dict[str, Any]],
    ) -> KOLWeightedSentimentResult:
        """Compute credibility-weighted sentiment polarity from a list of social posts.

        Each post dict should contain:
        - 'author': str (author username)
        - 'polarity': float (-1.0 to +1.0 raw sentiment polarity)
        - 'quality_score': float (optional 0.0 to 1.0 from DataQualityAuditor, default 1.0)
        """
        if not posts:
            return KOLWeightedSentimentResult(
                raw_unweighted_polarity=0.0,
                kol_weighted_polarity=0.0,
                total_posts=0,
                elite_alpha_count=0,
                contrarian_inverted_count=0,
                media_neutralized_count=0,
                confidence_score=0.0,
                summary_explanation="无发帖数据",
                post_breakdowns=[],
            )

        raw_sum = 0.0
        weighted_sum = 0.0
        total_abs_weight = 0.0

        elite_count = 0
        contrarian_count = 0
        media_count = 0
        breakdowns = []

        for p in posts:
            author = str(p.get("author", "anonymous")).strip()
            raw_pol = float(p.get("polarity", 0.0))
            q_score = float(p.get("quality_score", 1.0))

            profile = self.get_author_profile(author)
            w = profile.directional_weight

            raw_sum += raw_pol

            if profile.is_media:
                media_count += 1
                effective_contribution = 0.0
                action_note = "资讯媒体号(剥离方向权重)"
            elif profile.is_contrarian:
                contrarian_count += 1
                # Contrarian indicator: w is negative (-1.5), so positive raw_pol becomes negative contribution!
                effective_contribution = raw_pol * w * q_score
                total_abs_weight += abs(w * q_score)
                action_note = f"反向明灯({profile.win_rate_5d:.0%}胜率) -> 信号执行反向倒置!"
            else:
                if profile.tier in ("TIER_0_ELITE_KOL", "TIER_1_CORE_ALPHA", "TIER_2_SOLID_RESEARCHER"):
                    elite_count += 1
                    action_note = f"高胜率投研大V({profile.win_rate_5d:.0%}胜率) -> 权重放大 {w:.1f}x"
                else:
                    action_note = f"普通散户(低权基准 {w:.1f}x)"
                effective_contribution = raw_pol * w * q_score
                total_abs_weight += abs(w * q_score)

            weighted_sum += effective_contribution
            breakdowns.append({
                "author": author,
                "tier": profile.tier,
                "fans": profile.fans,
                "historical_win_rate_5d": round(profile.win_rate_5d, 3),
                "raw_polarity": round(raw_pol, 3),
                "applied_weight": w,
                "effective_contribution": round(effective_contribution, 3),
                "action_note": action_note,
            })

        raw_avg = round(raw_sum / len(posts), 4)
        if total_abs_weight > 0:
            weighted_avg = round(max(-1.0, min(1.0, weighted_sum / total_abs_weight)), 4)
        else:
            weighted_avg = 0.0

        confidence = min(1.0, round((elite_count * 0.35) + (contrarian_count * 0.25) + 0.2, 2))

        summary = (
            f"评估 {len(posts)} 条观点: 原始未加权情绪 {raw_avg:+.2f} -> "
            f"大V信誉加权后情绪 {weighted_avg:+.2f} "
            f"(含高胜率大V {elite_count} 人、反向明灯倒置 {contrarian_count} 人、资讯媒体去方向 {media_count} 人)"
        )

        return KOLWeightedSentimentResult(
            raw_unweighted_polarity=raw_avg,
            kol_weighted_polarity=weighted_avg,
            total_posts=len(posts),
            elite_alpha_count=elite_count,
            contrarian_inverted_count=contrarian_count,
            media_neutralized_count=media_count,
            confidence_score=confidence,
            summary_explanation=summary,
            post_breakdowns=breakdowns,
        )


