    for b in res.post_breakdowns:
        print(
            f"  - [{b['author']:<8}] Fans: {b['fans']:>7,} | 5D WinRate: {b['historical_win_rate_5d']*100:>4.1f}% | "
            f"Raw: {b['raw_polarity']:+.2f} -> Effective: {b['effective_contribution']:+.2f} ({b['action_note']})"
        )
